/* ============================ Peace In Pressure — site-wide brand layer ============================
   Tokens carry colour, type and radius (Design system). This file holds only what tokens cannot say. */

/* Accented capitals missing from Yacote fall back to Work Sans, wherever a name appears. */
@font-face { font-family: "Yacote"; src: url("/fonts/WorkSans.ttf") format("truetype"); font-weight: 100 900; font-display: swap; unicode-range: U+00C1, U+00C9, U+00D3, U+00D6, U+0150, U+00DA, U+00D1, U+010C, U+0106, U+0160, U+017D; }

html { scroll-behavior: smooth; background: #020617; overflow-x: clip; }
body { -webkit-font-smoothing: antialiased; overflow-x: clip;
  background: radial-gradient(120% 60% at 70% -10%, #0a2c46 0%, #041c30 40%, #020617 100%) no-repeat #020617; }
::selection { background: #d705dd; color: #fff; }

/* One container for the whole site: 1366px max, centred, fluid below it with 40 / 32 / 20px side padding. */
:root { --pip-w: 1366px; --pip-pad: 40px; }
@media (max-width: 1100px) { :root { --pip-pad: 32px; } }
@media (max-width: 640px) { :root { --pip-pad: 20px; } }
.bz-section > .bz-container { max-width: var(--pip-w); margin-inline: auto; padding-inline: var(--pip-pad); }

/* Spacing is set explicitly per band, so blocks carry no padding of their own. */
.bz-block { padding-block: 0; }
:where(.bz-col:not(.bz-sharedsection *)) > :where(.bz-block + .bz-block, .bz-block + .bz-row, .bz-row + .bz-block) { margin-top: var(--space-4); }

/* On this dark site the ink token is the text colour, so the prebuilt dark bands take the card surface instead. */
.bz-block--hero, .bz-block--statBand, .bz-block--serviceGrid, .bz-block--footer, .bz-section--bg-ink, .bz-col--bg-ink { background: var(--card); color: var(--ink); }


/* Display type is always Yacote, uppercase. */
.bz-headingblock :is(h1, h2, h3) { text-transform: uppercase; }
.bz-headingblock h1 { color: #f4fbff; }
.bz-headingblock :is(h1, h2) { letter-spacing: 0; white-space: pre-line; }
.bz-headingblock h1 { font-weight: 700; font-size: clamp(44px, 7vw, var(--text-h1)); line-height: .92; }
.bz-headingblock h2 { font-weight: 700; }
.bz-headingblock h3 { font-weight: 600; }
.bz-block p, .bz-block li, .bz-block blockquote { line-height: normal; }
body { line-height: normal; }
.bz-block p { font-size: var(--text-body); }
.bz-eyebrow { font-family: var(--font-heading); font-weight: 400; letter-spacing: .3em; }
.bz-text a, .bz-lede a { color: var(--accent); text-decoration: underline; }
.bz-text a:hover { color: var(--accent-dark); }
.bz-text strong { color: #f4fbff; font-weight: 600; }

/* Logos keep their set height (the block default is overridden by .bz-block img) */
.bz-block--logo .bz-logo__img { height: var(--bz-logo-h, 34px); width: auto; max-width: none; }

/* Buttons */
.bz-btn { font-family: var(--font-heading); font-weight: 600; font-size: 13px; letter-spacing: .12em; text-transform: uppercase; border-radius: 4px; padding: 14px 26px; line-height: 1; transition: transform .25s ease, border-color .25s ease, color .25s ease, filter .25s ease; }
.bz-btn--primary { background: linear-gradient(135deg, #00fbff, #00cdfd); color: #020617; border: 0; padding: 10px 22px; }
.bz-btn--primary:hover { background: linear-gradient(135deg, #00fbff, #00cdfd); filter: brightness(1.08); transform: translateY(-1px); }
.bz-btn--secondary { background: transparent; color: #00fbff; border: 1px solid #00cdfd; padding: 14px 28px; font-size: 14px; }
.bz-btn--secondary:hover { background: transparent; color: #00fbff; border-color: #00cdfd; filter: brightness(1.15); }
.bz-btn--link { color: #00cdfd; text-decoration: none; letter-spacing: .1em; }
.bz-btn--link:hover { color: #00fbff; }
[data-bz-node="fa-cta"] .bz-btn--primary, [data-bz-node="fa-close-cta"] .bz-btn--primary { padding: 16px 32px; font-size: 14px; }

/* Forms — field styling from the handoff (labels 13px muted, 48px controls, 6px radius) */
.bz-form { background: transparent; border: 0; padding: 0; max-width: none; gap: 18px; }
.bz-form__t { display: none; }
.bz-field { gap: 8px; }
.bz-field--half { flex: 1 1 calc(50% - 9px); min-width: min(100%, 220px); }
.bz-label { font-family: var(--font-body); font-weight: 400; font-size: 13px; letter-spacing: 0; line-height: normal; color: #9fb4c6; }
.bz-req { color: inherit; }
.bz-input, .bz-form input:not([type="checkbox"]):not([type="radio"]), .bz-form select, .bz-form textarea { height: 48px; min-height: 0; box-sizing: border-box; padding: 0 16px; background: rgba(4,28,48,0.7); border: 1px solid rgba(255,255,255,.14); border-radius: 6px; color: #eaf2f8; font-family: var(--font-body); font-size: 15px; font-weight: 400; line-height: normal; outline: none; color-scheme: dark; }
.bz-form select { padding: 0 14px; }
.bz-form textarea { height: auto; min-height: 150px; padding: 14px 16px; line-height: 1.6; resize: vertical; }
.bz-input:focus, .bz-form select:focus, .bz-form textarea:focus, .bz-form input:focus { border-color: #00cdfd; outline: none; }
.bz-input::placeholder { color: #6f8598; }
.bz-form select option { background: #041c30; color: #eaf2f8; }
.bz-form .bz-choices { flex-direction: row; flex-wrap: wrap; gap: 10px; }
.bz-form .bz-choice { display: flex; align-items: center; gap: 10px; padding: 12px 18px; border-radius: 6px; border: 1px solid rgba(255,255,255,0.14); background: rgba(4,28,48,0.7); font-size: 15px; color: #eaf2f8; cursor: pointer; line-height: normal; }
.bz-form .bz-choice input { accent-color: #00cdfd; width: 18px; height: 18px; margin: 3px 3px 3px 4px; padding: 0; min-height: 0; flex: none; }
.bz-form .bz-field--consent .bz-choice, .bz-form .bz-field--plain .bz-choice { padding: 0; border: 0; background: none; align-items: flex-start; gap: 12px; font-size: 15px; line-height: 1.5; color: #c4d4e2; }
.bz-form .bz-field--consent .bz-choice input { margin: 2px 0 0; }
.bz-form button[type="submit"] { font-family: var(--font-heading); font-weight: 600; letter-spacing: .12em; text-transform: uppercase; font-size: 14px; line-height: normal; color: #020617; background: linear-gradient(135deg, #00fbff, #00cdfd); border: 0; border-radius: 4px; padding: 15px 34px; cursor: pointer; flex: 0 0 auto; width: auto; align-self: flex-start; }
.bz-form a { color: var(--accent); }
.bz-form__status { font-size: 14px; color: #ff7aa8; }
.bz-form__status:empty { display: none; }

/* Rise-in on first view. Only armed once the script has run, so the editing canvas and no-JS visitors see everything. */
.pip-reveal-ready [data-bz-reveal] { opacity: 0; transform: translateY(30px); transition: opacity .8s ease, transform .8s ease; }
.pip-reveal-ready [data-bz-reveal].is-in { opacity: 1; transform: none; }

/* Long-form legal text — from the handoff */
[data-bz-node="legal"] > .bz-container { max-width: 820px; }
[data-bz-node="legal"] { padding: 40px 0 120px; }
[data-bz-node="legal"] .bz-block { margin: 0; }
[data-bz-node="legal-title"] h1 { font-size: clamp(40px, 6vw, 72px); line-height: .95; margin: 0 0 18px; color: #f4fbff; font-weight: 700; }
[data-bz-node="legal"] [data-bz-node="meta"].bz-block .bz-text p { margin: 0 0 36px; line-height: normal; font-size: 12px; letter-spacing: .2em; text-transform: uppercase; color: #6f8598; max-width: none; }
[data-bz-node="legal"] .bz-text p { font-size: 16px; line-height: 1.7; color: #c4d4e2; margin: 0 0 14px; max-width: none; text-wrap: pretty; }
[data-bz-node="legal"] .bz-text p:last-child { margin-bottom: 14px; }
[data-bz-node="legal"] [data-bz-node^="ul-"].bz-block .bz-text p { display: list-item; list-style: disc outside; margin: 0 0 6px 22px; line-height: 1.65; }
[data-bz-node="legal"] [data-bz-node^="ul-"].bz-block .bz-text p:last-child { margin-bottom: 18px; }
[data-bz-node="legal"] .bz-text strong { color: #f4fbff; font-weight: 600; }
[data-bz-node="legal"] .bz-headingblock h2 { font-size: 26px; line-height: 1.1; font-weight: 700; margin: 52px 0 16px; color: #f4fbff; scroll-margin-top: 110px; }
[data-bz-node="legal"] .bz-headingblock h3 { font-family: var(--font-body); text-transform: none; font-weight: 600; font-size: 18px; line-height: 1.35; letter-spacing: 0; color: #00cdfd; margin: 30px 0 10px; scroll-margin-top: 110px; }
[data-bz-node="legal"] [data-bz-node^="h3a"].bz-block .bz-text p { font-weight: 600; font-size: 18px; line-height: 1.35; color: #00cdfd; margin: 30px 0 10px; }
[data-bz-node="legal"] :is(h2, h3)[id] { scroll-margin-top: 110px; }
[data-bz-node="legal"] .bz-text a { color: #00cdfd; text-decoration: underline; text-underline-offset: auto; }

