// Rise-in on first view for the home page bands. Armed only once this script has run.
(function () {
  var names = ['news-stories', 'join-cta', 'partner-strip'];
  var hosts = names.map(function (n) { return document.querySelector('[data-bz-section="' + n + '"]'); }).filter(Boolean);
  if (!hosts.length || !('IntersectionObserver' in window)) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  hosts.forEach(function (h) { h.setAttribute('data-bz-reveal', ''); });
  document.documentElement.classList.add('pip-reveal-ready');
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } });
  }, { threshold: 0.1 });
  hosts.forEach(function (h) { io.observe(h); });
})();
